import sys

class TrieNode:
    __slots__ = ("children", "indices")
    def __init__(self):
        self.children = {}
        self.indices = []

def build_trie(strings):
    root = TrieNode()
    for idx, s in enumerate(strings):
        node = root
        for ch in s:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            node.indices.append(idx)
    return root

def find_prefix_indices(root, prefix):
    node = root
    for ch in prefix:
        if ch not in node.children:
            return None
        node = node.children[ch]
    return node.indices

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    pos = 0
    n = int(data[pos].strip())
    pos += 1
    strings = []
    for _ in range(n):
        if pos < len(data):
            strings.append(data[pos].rstrip('\n'))
            pos += 1
        else:
            strings.append('')
    q = 0
    if pos < len(data):
        q = int(data[pos].strip())
        pos += 1
    queries = []
    for _ in range(q):
        if pos < len(data):
            queries.append(data[pos].rstrip('\n'))
            pos += 1
        else:
            queries.append('')
    root = build_trie(strings)
    out_lines = []
    for pref in queries:
        indices = find_prefix_indices(root, pref)
        if indices is None:
            out_lines.append('')
        else:
            out_lines.append(' '.join(strings[i] for i in indices))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    main()
